month_map = {
    "jan.": "01", "fev.": "02", "mar.": "03", "abr.": "04", "mai.": "05",
    "jun.": "06", "jul.": "07", "ago.": "08", "set.": "09", "out.": "10",
    "nov.": "11", "dez.": "12"
}
data = calendario['DATA']

# Função para converter formato da data
def convert_date(date_str):
    parts = date_str.split()  
    day = parts[1]  
    month = month_map[parts[2]]  
    year = "2025"  
    return f"{year}-{month}-{day.zfill(2)}"  


aux = pd.DataFrame({"Original Date": data})
calendario["data"] = aux["Original Date"].apply(convert_date)
calendario['hora'] = np.where(calendario['HORA']=="A definir", None,calendario['HORA'])
def adicionar_uma_hora(valor):
    if isinstance(valor, str):  # Verificar se o valor é uma string válida
        try:
            # Tentar fazer a conversão e adicionar 1 hora
            return (datetime.strptime(valor, "%H:%M")).strftime("%H:%M")
        except ValueError:
            return valor  # Caso contrário, retorna o valor original (por exemplo, 'None')
    return valor  # Retorna o valor se não for string (como None ou NaN)

# Aplicar a função na coluna 'hora'
calendario['hora'] = calendario['hora'].apply(adicionar_uma_hora)
count_mandante =calendario['Mandante'].value_counts()
time_mais_frequente = count_mandante.idxmax()
calendario['time_em_casa'] = np.where(calendario['Mandante']==time_mais_frequente, True, False)
calendario['oponente'] = np.where(calendario['time_em_casa']== True, calendario['Visitante'], calendario['Mandante'])
calendario = calendario.reset_index()
calendario = calendario.drop(columns=['Mandante', 'Visitante', 'DATA', 'HORA', 'index'])
def criar_agenda(jogos):
    with open(f'agenda_{time}_2025.csv', mode='w', newline='') as file:
        writer = csv.writer(file)
        writer.writerow(["Subject", "Start Date", "Start Time", "End Date", "End Time"])
        
        for index, jogo in jogos.iterrows():
            data_inicio = jogo["data"]
            hora_inicio = jogo.get("hora")
            data_fim = data_inicio
            #se o jogo for fora de casa, o nome virá com Fora; se for em casa, virá com Casa
            fora = " Fora" if not jogo["time_em_casa"] else " Casa"
            if hora_inicio is None:
                # caso o jogo ainda não tenha horário definido
                writer.writerow([f"{time_mais_frequente} x {jogo['oponente']}{fora} - {jogo['campeonato']}", data_inicio, "", data_fim])
            else:
                hora_fim = (datetime.strptime(hora_inicio, "%H:%M") + timedelta(hours=2)).strftime("%H:%M")
                writer.writerow([f"{time_mais_frequente} x {jogo['oponente']}{fora} - {jogo['campeonato']}", data_inicio, hora_inicio, data_fim, hora_fim])
criar_agenda(calendario)